    for  i = 0; (i < Pla_ManCubeNum(p))  && (((pCube) = Pla_CubeIn(p, i)), 1); i++  {
        Mint = Vec_IntEntry(vMints, i);
        // inlining of macro Pla_CubeForEachLitIn
        // inlining of macro Pla_CubeForEachLit
        for  k = 0; (k < Pla_ManInNum(p))  && (((Lit) = Pla_CubeGetLit(pCube, k)), 1); k++  {
            Pla_CubeSetLit( pCube, k, ((Mint >> k) & 1) ? PLA_LIT_ONE : PLA_LIT_ZERO );
        }
    }
    // inlining of macro Pla_ForEachCubeOut
    for  i = 0; (i < Pla_ManCubeNum(p))  && (((pCube) = Pla_CubeOut(p, i)), 1); i++  {
        Pla_CubeSetLit( pCube, 0, PLA_LIT_ONE );
    }
    return p;
}
func Pla_ManPrimesDetector(nVars int32) *Pla_Man_t {
    var pName string // was [1000]byte in C

    var p *Pla_Man_t;
    var vMints *Vec_Int_t  = Pla_GenPrimes( nVars );
    pName = fmt.Sprintf("primes%02d", nVars);
    p = Pla_GenFromMinterms( pName, vMints, nVars );
    Vec_IntFree( vMints );
    return p;
}

/**Function*************************************************************

  Synopsis    []

  Description []

  SideEffects []

  SeeAlso     []

***********************************************************************/
func Pla_GenRandom(nVars int32, nNums int32, fNonZero int32) *Vec_Bit_t {
    var Mint, Count int32;
    var vBits *Vec_Bit_t  = Vec_BitStart( 1 << nVars );
    assert(nVars > 0 && nVars <= 30, "nVars > 0 && nVars <= 30");
    assert(nNums > 0 && nNums < (1 << (nVars - 1)), "nNums > 0 && nNums < (1 << (nVars - 1))");
    for  Count < nNums  {
        Mint = Gia_ManRandom(0) & ((1 << nVars) - 1);
        if (fNonZero != 0) && Mint == 0 {
            continue; }
        if Vec_BitEntry(vBits, Mint) {
            continue; }
        Vec_BitWriteEntry( vBits, Mint, 1 );
        Count++;
    }
    return vBits;
}
func Pla_ManGenerate(nInputs int32, nOutputs int32, nCubes int32, fVerbose int32) *Pla_Man_t {
    var p *Pla_Man_t;
    var vBits *Vec_Bit_t;
    var i, k, Count int32;
    var pCube *word;
    var Buffer string // was [1000]byte in C

    Buffer = fmt.Sprintf("%s_%d_%d_%d", "rand", nInputs, nOutputs, nCubes);
    p = Pla_ManAlloc( Buffer, nInputs, nOutputs, nCubes );
    // generate nCube random input minterms
    vBits = Pla_GenRandom( nInputs, nCubes, 0 );
    for  i = Count = 0; i < Vec_BitSize(vBits); i++  {
        if Vec_BitEntry(vBits, i) {
            pCube = Pla_CubeIn( p, Count++ );
            for  k = 0; k < nInputs; k++  {
                Pla_CubeSetLit( pCube, k, ((i >> k) & 1) ? PLA_LIT_ONE : PLA_LIT_ZERO );
            }
        }
    }
    assert(Count == nCubes, "Count == nCubes");
    Vec_BitFree( vBits );
    // generate nCube random output minterms
    if nOutputs > 1 {
        vBits = Pla_GenRandom( nOutputs, nCubes, 1 );
        for  i = Count = 0; i < Vec_BitSize(vBits); i++  {
            if Vec_BitEntry(vBits, i) {
                pCube = Pla_CubeOut( p, Count++ );
                for  k = 0; k < nOutputs; k++  {
                    Pla_CubeSetLit( pCube, k, ((i >> k) & 1) ? PLA_LIT_ONE : PLA_LIT_ZERO );
                }
            }
        }
        assert(Count == nCubes, "Count == nCubes");
        Vec_BitFree( vBits );

    } else {
        // inlining of macro Pla_ForEachCubeOut
        for  i = 0; (i < Pla_ManCubeNum(p))  && (((pCube) = Pla_CubeOut(p, i)), 1); i++  {
            Pla_CubeSetLit( pCube, 0, PLA_LIT_ONE );
        }
    }
    return p;
}

