func Pla_ManDist1Num(p *Pla_Man_t) int32 {
    var pCube1, pCube2 *word; 
    var i, k, Dist, Count int32;
    // inlining of macro Pla_ForEachCubeIn
    for  i = 0; (i < Pla_ManCubeNum(p))  && (((pCube1) = Pla_CubeIn(p, i)), 1); i++  {
    // inlining of macro Pla_ForEachCubeInStart
    for  k = i+1; (k < Pla_ManCubeNum(p))  && (((pCube2) = Pla_CubeIn(p, k)), 1); k++  {
        Dist = Pla_CubesAreDistance1( pCube1, pCube2, p.nInWords );
//        Dist = Pla_CubesAreConsensus( pCube1, pCube2, p->nInWords, NULL );
        Count += (Dist == 1);
    }
    }
    return Count;
}
